package hu.taliann.icesmp.playerprofile.api;
import java.util.*;
public record SelfPlayerProfileDto(PublicPlayerProfileDto publicProfile,Map<String,Long> wallets,long bankBalance,Map<String,Map<String,Long>> activeQuests,Set<String> completedQuests,Map<String,Set<String>> spellProvenance,String selectedSpell,List<String> favoriteSpells,Map<String,Long> spellMastery,Map<String,Long> professionExperience,Map<String,Integer> professionLevels,Map<String,String> preferences,Set<String> claimableRewards){
 public SelfPlayerProfileDto{Objects.requireNonNull(publicProfile);wallets=Map.copyOf(wallets==null?Map.of():wallets);activeQuests=deep(activeQuests);completedQuests=Set.copyOf(completedQuests==null?Set.of():completedQuests);spellProvenance=deepSet(spellProvenance);selectedSpell=selectedSpell==null?"":selectedSpell;favoriteSpells=List.copyOf(favoriteSpells==null?List.of():favoriteSpells);spellMastery=Map.copyOf(spellMastery==null?Map.of():spellMastery);professionExperience=Map.copyOf(professionExperience==null?Map.of():professionExperience);professionLevels=Map.copyOf(professionLevels==null?Map.of():professionLevels);preferences=Map.copyOf(preferences==null?Map.of():preferences);claimableRewards=Set.copyOf(claimableRewards==null?Set.of():claimableRewards);}
 private static Map<String,Map<String,Long>> deep(Map<String,Map<String,Long>> in){if(in==null)return Map.of();LinkedHashMap<String,Map<String,Long>> o=new LinkedHashMap<>();in.forEach((k,v)->o.put(k,Map.copyOf(v)));return Map.copyOf(o);}private static Map<String,Set<String>> deepSet(Map<String,Set<String>> in){if(in==null)return Map.of();LinkedHashMap<String,Set<String>> o=new LinkedHashMap<>();in.forEach((k,v)->o.put(k,Set.copyOf(v)));return Map.copyOf(o);}
}
